/**
 * ANA-4: thread the real run id into the scenario-prediction record path.
 *
 * `AnalysisOutput` carries no run_id, so the old `(analysis as { run_id?:
 * string }).run_id ?? run-${date}-${Date.now()}` cast always fell through to a
 * synthetic id, orphaning every prediction from its run (calibration join-back
 * is keyed on run_id, indexed `idx_outcomes_run`). The real id lives on
 * `services.runId`, set before any step runs. Use it verbatim when present; a
 * fallback remains only for the degenerate no-runId case and it is LOUD (warn)
 * and obviously synthetic so a join-back miss is debuggable, never a silent
 * date substitution.
 */
export function resolveScenarioRunId(runId: string | undefined, log: Logger): string {
  if (typeof runId === 'string' && runId.length > 0) return runId;
  const synthetic = `synthetic-run-${new Date().toISOString().slice(0, 10)}-${Date.now()}`;
  log.warn('scenario-outcomes.run-id-missing',
    `No real run id on services; scenario predictions will be orphaned from calibration join-back. Using synthetic id ${synthetic}.`);
  return synthetic;
}

